// Decodes the fetched file and returns one item per post that's due to fire.
// Each output item carries the original file's sha + full queue array so the
// later "Build Updated Queue" step doesn't need to re-fetch anything.
const fetched = $input.first().json;
const sha = fetched.sha;
const decoded = Buffer.from(fetched.content, 'base64').toString('utf-8');
const queue = JSON.parse(decoded);
const now = Date.now();

const due = queue.filter(
  (post) => post.status === 'queued' && new Date(post.scheduledFor).getTime() <= now,
);

return due.map((post) => ({
  json: {
    ...post,
    _sha: sha,
    _fullQueue: queue,
  },
}));

// Every item that reaches this node already posted successfully (a failed
// HTTP call upstream halts the run instead of continuing, since "Continue
// On Fail" is off on the OpenTweet node) — so it's safe to mark all of them.
const originalItems = $('Decode & Filter Due Posts').all();
if (originalItems.length === 0) {
  return [];
}

const postedIds = new Set(originalItems.map((item) => item.json.id));
const sha = originalItems[0].json._sha;
const fullQueue = originalItems[0].json._fullQueue;

const updatedQueue = fullQueue.map((post) =>
  postedIds.has(post.id) ? { ...post, status: 'posted' } : post,
);

const content = Buffer.from(JSON.stringify(updatedQueue, null, 2), 'utf-8').toString('base64');

return [
  {
    json: {
      sha,
      content,
      message: `chore: mark ${postedIds.size} post(s) as posted (n8n)`,
    },
  },
];
